 try:return p.resolve().relative_to(_tn_root).as_posix()
 except ValueError:return None
def _tn_read_bytes(p):
 k=_tn_key(p);return _tn_hist[k].encode('utf-8') if k in _tn_hist else _tn_bytes(p)
